INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422598, 16112, 'The Guardian', 'en', 'Uefa preparing to bring criminal claims against Gianni Infantino over World Cup sale', 'https://www.theguardian.com/football/2026/aug/27/uefa-preparing-to-bring-criminal-claims-against-gianni-infantino-over-world-cup-sale', 'Uefa says claims will be made in Switzerland It says claims relate to alleged criminal mismanagement Uefa is preparing to make a criminal complaint against Gianni Infantino for alleged “criminal mismanagement” in connection with his failed Fifa Forward Enterprise plan and has applied for the release of documents related to its conception. In an explosive escalation of the war engulfing football’s governing bodies, Uefa has made separate applications in the United States for information, including from Fifa and the investment firm Thrive Capital. Continue reading...', 'https://i.guim.co.uk/img/media/844e1a5b0ac35396af839b2c5e06ccc08af91fbd/648_86_2204_1763/master/2204.jpg?width=140&quality=85&auto=format&fit=max&s=e25c91aa60f912b68ac02f5284979b84', '2026-08-27T14:06:37+00:00', '2026-08-28T12:49:07.427337'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422726, 16112, 'France 24', 'en', 'UEFA prepares complaint against FIFA president Infantino', 'https://www.france24.com/en/uefa-prepares-complaint-against-fifa-president-infantino', 'UEFA is preparing a legal complaint against FIFA president Gianni Infantino over what it calls "unfair management" linked to his abandoned plan to open the World Cup to private investors. The European governing body has meanwhile suspended its threat to boycott FIFA competitions next season after receiving assurances from FIFA, but says it will keep pressure on Infantino ahead of his re-election bid in March.', 'https://s.france24.com/media/display/fe2d6230-a2ba-11f1-abde-005056bfb2b6/w:1024/p:16x9/EN-20260828-071131-071305-CS.jpg', '2026-08-28T09:08:42+00:00', '2026-08-28T12:49:23.893186'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
